import NotificationService from '../notification_service';import { FirebaseFirestore, FieldValue } from '@firebase/firestore';import { FirebaseMessaging } from '@firebase/messaging';jest.mock('@firebase/firestore');jest.mock('@firebase/messaging');describe('NotificationService', () => {  let notificationService;  let mockFirestore;  let mockMessaging;  beforeEach(() => {    mockFirestore = {      collection: jest.fn().mockReturnThis(),      doc: jest.fn().mockReturnThis(),      runTransaction: jest.fn(),      where: jest.fn().mockReturnThis(),      orderBy: jest.fn().mockReturnThis(),      limit: jest.fn().mockReturnThis(),      get: jest.fn(),    };    mockMessaging = {      getToken: jest.fn().mockResolvedValue('test-token'),    };    FirebaseFirestore.mockImplementation(() => mockFirestore);    FirebaseMessaging.mockImplementation(() => mockMessaging);    notificationService = new NotificationService();  });  describe('registerToken', () => {    it('registers FCM token for user', async () => {      mockFirestore.runTransaction.mockImplementation(async (callback) => {        await callback({          update: jest.fn(),        });      });      const result = await notificationService.registerToken('user123');      expect(result).toBe(true);      expect(mockMessaging.getToken).toHaveBeenCalled();      expect(mockFirestore.runTransaction).toHaveBeenCalled();    });    it('returns false if token is null', async () => {      mockMessaging.getToken.mockResolvedValue(null);      const result = await notificationService.registerToken('user123');      expect(result).toBe(false);    });    it('handles errors during registration', async () => {      mockMessaging.getToken.mockRejectedValue(new Error('Test error'));      const result = await notificationService.registerToken('user123');      expect(result).toBe(false);    });  });  describe('getRecentNotifications', () => {    it('returns recent notifications for user', async () => {      const mockSnapshot = {        docs: [          { data: () => ({ id: '1', message: 'Test notification' }) },        ],      };      mockFirestore.get.mockResolvedValue(mockSnapshot);      const result = await notificationService.getRecentNotifications('user123');      expect(result).toEqual([{ id: '1', message: 'Test notification' }]);      expect(mockFirestore.collection).toHaveBeenCalledWith('notifications');      expect(mockFirestore.where).toHaveBeenCalledWith('userId', 'isEqualTo', 'user123');      expect(mockFirestore.orderBy).toHaveBeenCalledWith('createdAt', 'desc');      expect(mockFirestore.limit).toHaveBeenCalledWith(20);      expect(mockFirestore.get).toHaveBeenCalled();    });    it('returns empty array on error', async () => {      mockFirestore.get.mockRejectedValue(new Error('Test error'));      const result = await notificationService.getRecentNotifications('user123');      expect(result).toEqual([]);    });  });});